-- Atualiza FK_GESTOR_ID para recursos
-- Evita erro 1093 (não pode atualizar tabela e selecionar dela na mesma subquery)
SET @gestor_id = (SELECT ID FROM FUNCIONARIO WHERE EMAIL='rafael.gomes@pam.local' LIMIT 1);
-- Include a key column condition to satisfy MySQL Workbench safe-update mode (avoid Error 1175)
UPDATE FUNCIONARIO SET FK_GESTOR_ID = @gestor_id WHERE TIPO_PERFIL = 'recurso' AND FK_GESTOR_ID IS NULL AND ID > 0;

