-- Atualiza marcos/entregas para refletir progresso
UPDATE MARCO SET ENTREGAS_CONCLUIDAS = 1 WHERE TITULO = 'Lançamento MVP' AND PROJETO_ID = (SELECT ID FROM PROJETOS WHERE NOME='Projeto Aurora' LIMIT 1);
UPDATE ENTREGA SET STATUS = 'concluido' WHERE TITULO = 'Backend' AND MARCO_ID = (SELECT ID FROM MARCO WHERE TITULO='Lançamento MVP' LIMIT 1);

-- Ajusta datas dos lançamentos e horas extras para período Aug-Oct 2026 (até hoje 2026-10-27 18:00)
-- Distribui DATA_LANCAMENTO entre 2026-08-01 e 2026-10-27 com horário coerente; limita HORA_FIM a 18:00
UPDATE LANCAMENTOS_HORAS L
JOIN FUNCIONARIO F ON L.USUARIO_ID = F.ID
SET L.DATA_LANCAMENTO = LEAST(DATE_ADD('2026-08-01', INTERVAL (L.ID % 90) DAY), '2026-10-27'),
    L.HORA_INICIO = (CASE WHEN L.DURACAO_MINUTOS > 480 THEN '08:00:00' WHEN L.DURACAO_MINUTOS > 240 THEN '09:00:00' ELSE '10:00:00' END),
    L.HORA_FIM = (CASE WHEN L.DURACAO_MINUTOS > 480 THEN LEAST(ADDTIME('08:00:00', SEC_TO_TIME(L.DURACAO_MINUTOS*60)), '18:00:00')
                     WHEN L.DURACAO_MINUTOS > 240 THEN LEAST(ADDTIME('09:00:00', SEC_TO_TIME(L.DURACAO_MINUTOS*60)), '18:00:00')
                     ELSE LEAST(ADDTIME('10:00:00', SEC_TO_TIME(L.DURACAO_MINUTOS*60)), '18:00:00') END)
WHERE F.FK_GESTOR_ID = (SELECT ID FROM FUNCIONARIO WHERE EMAIL='rafael.gomes@pam.local')
  AND L.DATA_LANCAMENTO IS NOT NULL
  AND L.ID > 0;

-- Garantir que lançamentos especificamente marcados como hora extra fiquem em período recente
UPDATE LANCAMENTOS_HORAS L
JOIN FUNCIONARIO F ON L.USUARIO_ID = F.ID
SET L.DATA_LANCAMENTO = LEAST(DATE_ADD('2026-10-01', INTERVAL (L.ID % 27) DAY), '2026-10-27'),
    L.HORA_INICIO = '08:00:00',
    L.HORA_FIM = LEAST(ADDTIME('08:00:00', SEC_TO_TIME(L.DURACAO_MINUTOS*60)), '18:00:00')
WHERE F.FK_GESTOR_ID = (SELECT ID FROM FUNCIONARIO WHERE EMAIL='rafael.gomes@pam.local')
  AND L.DESCRICAO_ATIVIDADE LIKE 'Hora extra%'
  AND L.ID > 0;

-- Atualizar solicitações de hora extra para terem DATA_INICIO/DATA_FIM coerentes com lançamentos
UPDATE SOLITICACAO S
JOIN (
  -- use MAX to be compatible with ONLY_FULL_GROUP_BY: take the most recent hora extra per user
  SELECT USUARIO_ID, MAX(DATA_LANCAMENTO) AS DATA_LANCAMENTO
  FROM LANCAMENTOS_HORAS
  WHERE DESCRICAO_ATIVIDADE LIKE 'Hora extra%'
  GROUP BY USUARIO_ID
) L ON S.USUARIO_ID = L.USUARIO_ID
SET S.DATA_INICIO = L.DATA_LANCAMENTO, S.DATA_FIM = L.DATA_LANCAMENTO
WHERE S.TIPO = 'hora_extra' AND S.DATA_INICIO IS NULL AND S.ID > 0;

COMMIT;
